config.solutionCode:
// Simula una BD con lista en memoria para poder ejecutar
List<Estudiante> listaEstudiantes = new List<Estudiante>();

// Clase Estudiante
public class Estudiante {
    // Propiedades
    public string Nombre { get; set; }
    public int Edad { get; set; }
    public string Grado { get; set; }

    // Constructor
    public Estudiante(string nombre, int edad, string grado) {
        Nombre = nombre;
        Edad = edad;
        Grado = grado;
    }
}

// Clase GestorEstudiantes
public class GestorEstudiantes {
    // Operaciones CRUD
    public void CrearEstudiante(Estudiante estudiante) {
        listaEstudiantes.Add(estudiante);
    }

    public Estudiante LeerEstudiante(string nombre) {
        return listaEstudiantes.Find(e => e.Nombre == nombre);
    }

    public void ActualizarEstudiante(Estudiante estudiante) {
        Estudiante existente = listaEstudiantes.Find(e => e.Nombre == estudiante.Nombre);
        if (existente != null) {
            existente.Edad = estudiante.Edad;
            existente.Grado = estudiante.Grado;
        }
    }

    public void EliminarEstudiante(string nombre) {
        Estudiante estudiante = listaEstudiantes.Find(e => e.Nombre == nombre);
        if (estudiante != null) {
            listaEstudiantes.Remove(estudiante);
        }
    }
}

class Program {
    static void Main() {
        GestorEstudiantes gestor = new GestorEstudiantes();

        Estudiante estudiante1 = new Estudiante("Juan Pérez", 20, "Primero");
        gestor.CrearEstudiante(estudiante1);

        Estudiante leido = gestor.LeerEstudiante("Juan Pérez");
        Console.WriteLine(leido.Nombre + " - " + leido.Edad + " - " + leido.Grado);

        estudiante1.Edad = 21;
        gestor.ActualizarEstudiante(estudiante1);

        leido = gestor.LeerEstudiante("Juan Pérez");
        Console.WriteLine(leido.Nombre + " - " + leido.Edad + " - " + leido.Grado);

        gestor.EliminarEstudiante("Juan Pérez");

        Console.WriteLine("Fin del programa");
    }
}
